class Account {
    private double balance;

    // CONSTRUCTOR: same name as class, NO return type
    public Account(double opening) {
        this.balance = opening;         // initialize state on creation
    }

    // METHOD: any name, must have a return type (void here)
    public void deposit(double amt) {
        balance += amt;                 // behavior called on an existing object
    }

    // WARNING: this is a METHOD, not a constructor!
    // public void Account() { }       // <-- 'void' makes it an ordinary method
}

Account a = new Account(100);           // constructor runs once, automatically
a.deposit(50);                          // method called explicitly, balance = 150
a.deposit(25);                          // called again — methods have no limit
```

